			/**
			 * 목록 데이터 조회 서브미션 호출
			 * @param psStatus - 조회 상태(저장 후 조회인 경우에는 'save' 구분값 넘김)
			 */
			function doDtlList(psStatus) {
			    
			    //조회 서브미션 호출
			    util.Submit.send(app, "subDtlList", function(pbSuccess) {
			        
			        if (pbSuccess) {
			            
			            if (psStatus) {
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			            } else {
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }
			            
			            var dsBoardList = app.lookup("dsBoardList");
			            var vaBoardDelYN = dsBoardList.getValue(0, "DEL_YN");
			            
			            var userGroupAuthrt = user["GROUP_AUTHRT_SE_CD"];
			            
			            if (vaBoardDelYN == "Y") {
			                util.Control.setEnable(app, false, ["btnRevise"]);
			                util.Control.setEnable(app, false, ["btnDelete"]);
			            } else {
			                if (userGroupAuthrt != 340) {
			                    util.Control.setEnable(app, true, ["btnDelete"]);
			                } else {
			                    util.Control.setEnable(app, false, ["btnDelete"]);
			                }
			                util.Control.setEnable(app, true, ["btnRevise"]);
			            }
			            
			            app.lookup("grpBoardDtl").redraw();
			            
			            doRplyList();
			        }
			    });
			};

			/**
			 * 데이터 저장 서브미션 호출
			 * @param psStatus - 요청 상태
			 */
			function doSave(psStatus) {
			    
			    // 저장 서브미션 호출
			    util.Submit.send(app, "subSave", function(pbSuccess) {
			        if (pbSuccess) {
			            // 저장여부
			            mbIsSave = true;
			            // 삭제시 재조회
			            if (psStatus == "DELETE") {
			                var voHostApp = app.getHostAppInstance();
			                if (voHostApp.hasAppMethod("selectMdiItem")) {
			                    voHostApp.callAppMethod("selectMdiItem", 1, mbIsSave);
			                }
			            } else {
			                // 저장시 재조회를 위한 게시글 시퀀스값 저장            
			                var vnBbsENo = app.lookup("subSave").getMetadata("BBSCTT_ESNTAL_NO");
			                util.DataMap.setValue(app, "dmDtlParam", "BBSCTT_ESNTAL_NO", vnBbsENo);
			                
			                if (ValueUtil.isNull(vnBbsENo)) {
			                    vnBbsENo = util.DataSet.getValue(app, "dsBoardList", 0, "BBSCTT_ESNTAL_NO");
			                    util.DataMap.setValue(app, "dmDtlParam", "BBSCTT_ESNTAL_NO", vnBbsENo);
			                }
			                
			                console.log("vnBbsENo ::" + vnBbsENo);
			                doDtlList("save");
			            }
			            
			        }
			    });
			}

