			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e) {
			    var btnSave = e.control;
			    
			    var vcEditer = app.lookup("cmnHtmlEditor");
			    var dsBoardList = app.lookup("dsBoardList");
			    
			    dsBoardList.setValue(0, "BBSCTT_CN", vcEditer.getValue());
			    
			    console.log(dsBoardList);
			    
			    // 입력 프리폼 유효성 체크
			    if (!util.validate(app, "grpBoardDtl")) return false;
			    
			    // 변경사항이 있을때 저장 작업
			    if (util.FreeForm.isModified(app, "grpBoardDtl")) {
			        
			        util.Msg.confirm(app, "CRM-M001", null, function() {
			            util.Submit.send(app, "subSave", function(pbSuccess) {
			                if (pbSuccess) {
			                    // 저장시 재조회를 위한 게시글 시퀀스값 저장            
			                    var vnBbsENo = app.lookup("subSave").getMetadata("BBSCTT_ESNTAL_NO");
			                    util.DataMap.setValue(app, "dmDtlParam", "BBSCTT_ESNTAL_NO", vnBbsENo);
			                    
			                    if (ValueUtil.isNull(vnBbsENo)) {
			                        vnBbsENo = util.DataSet.getValue(app, "dsBoardList", 0, "BBSCTT_ESNTAL_NO");
			                        util.DataMap.setValue(app, "dmDtlParam", "BBSCTT_ESNTAL_NO", vnBbsENo);
			                    }
			                    
			                    // CRUD에 따른 화면 구성 함수
			                    setDtlCrud("READ");
			                    
			                    // 게시글(원글) 및 답글 재조회
			                    doDtlList();
			                }
			            });
			        }, null, "안내");
			    
			    // 변경사항이 없을때 알림
			    } else {     
			        util.Msg.alert(app, "INF-M006");
			    }
			    
			}

